/*
 * A042703  Denominators of continued fraction convergents to sqrt(881).
 * https://oeis.org/A042703
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) is the denominator of the nth continued‑fraction convergent
 *            of sqrt(881). Recurrence: q_{-1}=0, q_0=1, a_0=29, and for k≥1,
 *            a_k generated by the standard continued‑fraction algorithm, q_k
 *            = a_k * q_{k-1} + q_{k-2}
 * Range:     u8 n <= 4, u16 n <= 12, u32 n <= 24, u64 n <= 45, u128 n <= 86,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>
/* seq_t and idx_t are supplied by the build system. */

static const idx_t SQRTH = 29;      /* floor(sqrt(881)) */
static const idx_t D     = 881;     /* the radicand */

/* cache of computed denominators */
static seq_t *cache   = NULL;
static size_t cache_cap = 0;
static idx_t  cache_len = 0;

/* state of continued‑fraction generation */
static idx_t cf_m = 0;      /* current m */
static idx_t cf_d = 1;      /* current d */
static idx_t cf_a = SQRTH;  /* current a ; starts with a_0 */

/* state of recurrence for q */
static seq_t q_nm2 = 0;  /* q_{-1} */
static seq_t q_nm1 = 1;  /* q_0 */

/* ensure that cache contains terms up to index n */
static void ensure_up_to(idx_t n)
{
    if (n < cache_len)
        return;

    /* grow cache if necessary */
    if (cache_cap < (size_t)(n + 1)) {
        size_t newcap = cache_cap ? cache_cap : 16;
        while (newcap < (size_t)(n + 1))
            newcap <<= 1;
        seq_t *tmp = (seq_t *)realloc(cache, newcap * sizeof(seq_t));
        cache = tmp;
        cache_cap = newcap;
    }

    for (idx_t k = cache_len; k <= n; ++k) {
        if (k == 0) {
            cache[0] = (seq_t)1;
            /* prepare for next coefficient a_1 */
            idx_t m_next = cf_d * cf_a - cf_m;
            idx_t d_next = (D - m_next * m_next) / cf_d;
            idx_t a_next = (SQRTH + m_next) / d_next;
            cf_m = m_next; cf_d = d_next; cf_a = a_next;
        } else {
            seq_t qk = (seq_t)cf_a * q_nm1 + q_nm2;
            cache[k] = qk;
            /* shift recurrence variables */
            q_nm2 = q_nm1;
            q_nm1 = qk;
            /* compute next continued‑fraction coefficient */
            idx_t m_next = cf_d * cf_a - cf_m;
            idx_t d_next = (D - m_next * m_next) / cf_d;
            idx_t a_next = (SQRTH + m_next) / d_next;
            cf_m = m_next; cf_d = d_next; cf_a = a_next;
        }
    }
    cache_len = n + 1;
}

seq_t a(idx_t n)
{
    ensure_up_to(n);
    return cache[n];
}
